import * as T from './vendor/three.module.js';
import{seeded}from'./math.js';import{regions,galaxies}from'./world.js';import{bodyPositions,orbitPoint,encounterParameters}from'./orbits.js';
export class LivingSpace{
 constructor(scene,data){this.scene=scene;this.data=data;this.belts=[];this.galaxies=[];this.paths=[];this.matrix=new T.Object3D();this.position=new T.Vector3();this.registry=new Map();this.mobile=innerWidth<700;const rng=seeded(98231);const geometry=new T.IcosahedronGeometry(1,0);this.sharedRock=geometry;
 for(const region of regions){const available=data.filter(d=>d.rare&&(d.region===region.id));const pool=available.length?available:data.filter(d=>d.rare);const count=this.mobile?28:52;const material=new T.MeshStandardMaterial({color:region.color,roughness:1,flatShading:true});const mesh=new T.InstancedMesh(geometry,material,count);mesh.instanceMatrix.setUsage(T.DynamicDrawUsage);mesh.frustumCulled=false;mesh.boundingSphere=new T.Sphere(new T.Vector3(...region.center),195);mesh.userData.belt=region.id;scene.add(mesh);const particles=[];for(let i=0;i<count;i++){const d=pool[i%pool.length],key=`${region.id}:${i}`;const item={key,id:d.id,region:region.id,index:i,radius:92+rng()*90,phase:rng()*Math.PI*2,speed:.025+rng()*.045,inclination:(rng()-.5)*.8,size:.5+rng()*.65,position:new T.Vector3(),variant:encounterParameters(d,i+region.id.length)};particles.push(item);this.registry.set(key,item)}this.belts.push({mesh,particles,region})}
 for(const [gi,g]of galaxies.entries()){const n=this.mobile?2200:4200,rng=seeded(gi+321),positions=new Float32Array(n*3),colors=new Float32Array(n*3),color=new T.Color(g.color);for(let i=0;i<n;i++){const radius=25+Math.pow(rng(),.65)*(gi===0?400:240),arm=i%3/3*Math.PI*2,angle=arm+radius*.022+(rng()-.5)*.55;positions[i*3]=Math.cos(angle)*radius;positions[i*3+1]=(rng()-.5)*(18+radius*.07);positions[i*3+2]=Math.sin(angle)*radius;const strength=.25+rng()*.6;colors[i*3]=color.r*strength;colors[i*3+1]=color.g*strength;colors[i*3+2]=color.b*strength}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.BufferAttribute(positions,3));geo.setAttribute('color',new T.BufferAttribute(colors,3));const cloud=new T.Points(geo,new T.PointsMaterial({vertexColors:true,size:1.35,transparent:true,opacity:.58,depthWrite:false,blending:T.AdditiveBlending}));cloud.position.fromArray(g.center);cloud.rotation.x=gi===0?.2:-.3;scene.add(cloud);this.galaxies.push(cloud)}
 for(const d of data.filter(d=>d.kind==='planet'||d.kind==='moon')){const parent=d.kind==='moon'?data.find(x=>x.id===d.parent):null,center=parent?parent.pos:regions.find(r=>r.id===d.region).center,points=[];for(let i=0;i<=96;i++)points.push(new T.Vector3(...orbitPoint([0,0,0],d.orbit.radius,i/96*Math.PI*2,0,d.orbit.inclination,0)));const path=new T.Line(new T.BufferGeometry().setFromPoints(points),new T.LineBasicMaterial({color:d.color,transparent:true,opacity:.13,depthWrite:false}));path.position.fromArray(center);scene.add(path);this.paths.push({path,parentId:parent?.id})}
 this.update(0,new T.Vector3(0,0,30));
 }
 update(time,camera){this.positions=bodyPositions(this.data,regions,time);for(const belt of this.belts){const center=new T.Vector3(...belt.region.center);belt.mesh.visible=center.distanceToSquared(camera)<1100**2;for(const p of belt.particles){p.position.fromArray(orbitPoint(belt.region.center,p.radius,p.phase,p.speed,p.inclination,time));if(!belt.mesh.visible)continue;this.matrix.position.copy(p.position);this.matrix.rotation.set(time*.13+p.phase,time*.17+p.phase,p.phase);this.matrix.scale.set(p.size*1.4,p.size*.75,p.size);this.matrix.updateMatrix();belt.mesh.setMatrixAt(p.index,this.matrix.matrix)}if(belt.mesh.visible)belt.mesh.instanceMatrix.needsUpdate=true}this.galaxies.forEach((g,i)=>g.rotation.y=time*(i%2?-.002:.002));for(const item of this.paths)if(item.parentId)item.path.position.fromArray(this.positions.get(item.parentId));}
 get(key){return this.registry.get(key)}
 target(id,key){if(key)return this.get(key)?.position;const p=this.positions.get(id);return p?new T.Vector3(...p):null}
 pick(ray){const hits=ray.intersectObjects(this.belts.filter(b=>b.mesh.visible).map(b=>b.mesh));const hit=hits[0];if(!hit||hit.instanceId===undefined)return null;return{...this.get(`${hit.object.userData.belt}:${hit.instanceId}`),distance:hit.distance}}
 nearby(camera,caught){let best=null,distance=Infinity;for(const p of this.registry.values()){if(caught?.has(p.key))continue;const d=p.position.distanceToSquared(camera);if(d<distance){best=p;distance=d}}return best?{...best,distance:Math.sqrt(distance)}:null}
 dispose(){for(const b of this.belts){this.scene.remove(b.mesh);b.mesh.dispose();b.mesh.material.dispose()}this.sharedRock.dispose();for(const g of this.galaxies){this.scene.remove(g);g.geometry.dispose();g.material.dispose()}for(const p of this.paths){this.scene.remove(p.path);p.path.geometry.dispose();p.path.material.dispose()}this.registry.clear()}
}
